def clean(df):
    df = df.copy()
    for c in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        df[c] = pd.to_numeric(df[c], errors='coerce')
    df['island'] = df['island'].astype(str).str.strip()
    df['species'] = df['species'].astype(str).str.strip().replace({'Adeile': 'Adelie'})
    df['sex'] = df['sex'].astype(str).str.strip().str.lower().replace({'nan': None})
    df.loc[df['body_mass_g'] > 6500, 'body_mass_g'] = df.loc[df['body_mass_g'] > 6500, 'body_mass_g'] / 1000
    df = df.drop_duplicates()
    return df

def answer(df):
    g = df.groupby('island')['penguin_id'].count()
    return {k: int(v) for k, v in g.items()}
